function buildExportSvg(){if(globalThis.patternProductionUI)return globalThis.patternProductionUI.exportSvg();const v=vectorData(),parts=v.pieces.map(p=>`<g data-piece="${safe(p.name)}"><title>${safe(p.name)} · cắt ${p.quantity}</title><path d="${svgCutPath(p)}" fill="none" stroke="#000000" stroke-width="0.35" stroke-dasharray="none"/>${p.notches.map(q=>`<path d="M ${q.x-2} ${q.y-2} l 4 4 m 0 -4 l -4 4" stroke="#c04d45" stroke-width="0.4" fill="none"/>`).join('')}${p.holes.map(q=>`<circle cx="${q.x.toFixed(3)}" cy="${q.y.toFixed(3)}" r="${(q.diameter/2).toFixed(3)}" fill="none" stroke="#9c4c73" stroke-width="0.35"/>`).join('')}${p.folds.map(l=>`<path d="${path(l)}" fill="none" stroke="#3174af" stroke-width="0.25" stroke-dasharray="3 2"/>`).join('')}<text x="${p.label.x}" y="${p.label.y}" font-size="3.5" fill="#164831">${safe(visiblePieceLabel(p.name))}${visiblePieceLabel(p.name)?` · cắt ${p.quantity}`:""}</text>${$('showDimensions').checked?svgDimensions(p.dimensions):''}</g>`).join(''),svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${v.width.toFixed(2)}mm" height="${v.height.toFixed(2)}mm" viewBox="0 0 ${v.width.toFixed(3)} ${v.height.toFixed(3)}"><title>RAPMAU Rập Mẫu · ${v.paperSize} ${v.width} × ${v.height} mm</title><rect x="0.5" y="0.5" width="${v.width-1}" height="${v.height-1}" stroke="#aabbb0" stroke-width="0.2" fill="none"/>${parts}${projectCalibration?`<rect x="${projectCalibration.x}" y="${projectCalibration.y}" width="50" height="50" fill="none" stroke="#164831" stroke-width=".25"/><text x="${projectCalibration.x+2}" y="${projectCalibration.y+7}" font-size="3.5">50 × 50 mm · 100%</text>`:""}${exportNotes().map(a=>`<text x="${(a.x/(draftScale||1)).toFixed(3)}" y="${(a.y/(draftScale||1)).toFixed(3)}" font-family="${safe(a.font)}" font-size="${a.size}" font-weight="${a.bold?'bold':'normal'}" fill="${safe(a.color)}">${safe(a.text)}</text>`).join('')}</svg>`;return svg.replace('</svg>',(globalThis.patternPaperTools?.svg()||'')+'</svg>')}
