$('productType').onchange=()=>{const examples={'vi-cuc':[105,90],'vi-giay-to':[130,180],'bao-kinh':[170,70],'tui':[120,80],'day-nit':[1200,35]};const size=examples[$('productType').value];if(size){snapshot();$('overallWidth').value=size[0];$('overallHeight').value=size[1];committedDimensions={width:String(size[0]),height:String(size[1])};draftScale=null;measure()}};
