$('readImageDimensions').onclick=readImageDimensions;

function syncActiveDimensions(){const p=piece(),b=p.points.length>=3?core.bounds(core.sampleCurve(p.points,p.handles)):null,scale=p.mmPerPixel||(!p.needsDimensions&&pxPerMm?{x:1/pxPerMm,y:1/pxPerMm}:null);$('activeWidthMm').value=b&&scale?Number(((b.maxX-b.minX)*scale.x).toFixed(2)):'';$('activeHeightMm').value=b&&scale?Number(((b.maxY-b.minY)*scale.y).toFixed(2)):'';}
$('setActiveDimensions').onclick=()=>{const p=piece(),w=Number($('activeWidthMm').value),h=Number($('activeHeightMm').value);if(!p.closed||p.points.length<3)return status('Vẽ khép kín chi tiết trước khi nhập số đo.');if(![w,h].every(n=>Number.isFinite(n)&&n>=5&&n<=5000))return status('Nhập rộng và cao từ 5 đến 5000 mm.');snapshot();const b=core.bounds(core.sampleCurve(p.points,p.handles));p.mmPerPixel={x:w/(b.maxX-b.minX),y:h/(b.maxY-b.minY)};draftScale=pxPerMm=draftScale||1;chosenPieces=new Set([active]);syncPiece();stagePieces(true)};
$('useRegionPiece').onclick=()=>{if(!image||!region||region.w<5||region.h<5){chooseMode('region');return status('Kéo khung sát chi tiết muốn bổ sung rồi bấm Dùng khung làm chi tiết.')}snapshot();const r=region;pieces.push({...fresh(`Chi tiết bổ sung ${pieces.length+1}`),needsDimensions:!currentPdfPage,points:[{x:r.x,y:r.y},{x:r.x+r.w,y:r.y},{x:r.x+r.w,y:r.y+r.h},{x:r.x,y:r.y+r.h}],closed:true});active=pieces.length-1;chosenPieces=new Set([active]);selected=-1;hiddenPrevious=false;chooseMode('edit');syncPiece();status('Đã tạo viền theo khung chọn. Kéo điểm để khớp chi tiết, nhập rộng/cao rồi đưa lên giấy. Các chi tiết cũ được giữ.');};

// Saved pattern versions retain both source geometry and the arranged sheet.
let projectReferenceKey=null,projectSourceFile=null;
for(const id of ['photo','pdfFile'])$(id).addEventListener('change',e=>{projectSourceFile=e.target.files?.[0]||null;projectReferenceKey=null;projectCalibration=null;window.dispatchEvent(new Event('pattern-source-changed'))});
let sourceTemplate=null;
globalThis.patternProject={
 capture(){return {sourceTemplate,schema:1,units:'mm',state:captureState(),paper:staged?vectorData():null,calibration:projectCalibration,referenceKey:projectReferenceKey,imageInfo:image?{width:image.width,height:image.height,blank:!!image.blank,pdfWidthMm:image.pdfWidthMm,pdfHeightMm:image.pdfHeightMm,currentPdfPage}:null,photoName}},
 sourceFile:()=>projectSourceFile,
 async reference(){if(!image||image.blank)return null;const c=document.createElement('canvas');c.width=image.width;c.height=image.height;c.getContext('2d').drawImage(image,0,0);return new Promise(resolve=>c.toBlob(resolve,'image/png'))},
 setReference(key){projectReferenceKey=key},
 async restore(doc){sourceTemplate=doc.sourceTemplate||null;if(doc.referenceDataUrl){if(!/^data:image\/(png|jpeg|webp);base64,/.test(doc.referenceDataUrl))throw Error('Ảnh tham chiếu không hợp lệ.');const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('Không đọc được ảnh tham chiếu.'));img.src=doc.referenceDataUrl});image=img}else if(doc.referenceKey){throw Error('File này chỉ chứa tham chiếu kho nội bộ. Hãy mở tại ERUCO và dùng Lưu bản rập về máy để kèm ảnh trước khi chuyển sang RAPMAU.')}else image={width:doc.imageInfo?.width||1189,height:doc.imageInfo?.height||841,blank:true};if(doc.imageInfo){image.pdfWidthMm=doc.imageInfo.pdfWidthMm;image.pdfHeightMm=doc.imageInfo.pdfHeightMm}currentPdfPage=doc.imageInfo?.currentPdfPage??null;projectReferenceKey=doc.referenceKey;projectSourceFile=null;photoName=doc.photoName||'Bộ rập đã lưu';projectCalibration=doc.calibration||null;history=[];redoHistory=[];restoreState(doc.state);fitDraft();$('photoName').textContent=photoName;status('Đã mở phiên bản rập. Dùng Lưu bản rập để tải phiên bản mới về máy.');},
 metadata(index,name,quantity,role){const p=pieces[index];if(!p)return; snapshot(false);p.name=name.trim();p.quantity=quantity;p.lineRole=role;p.roleConfirmed=true;const placed=staged?.pieces.find(q=>q.sourceIndex===index);if(placed)Object.assign(placed,{name:p.name,quantity,lineRole:role,roleConfirmed:true});syncPiece();renderPaper()},
 calibration(value){snapshot(false);projectCalibration=value;$('reviewConfirmed').checked=false;renderPaper()},
 focus(index){active=index;chooseMode('edit');syncPiece();showWorkspace('edit')},
 exportSvg:()=>buildExportSvg(),
};

$('quickPencil').onclick=()=>chooseMode('pencil');
function finishPencil(e){
 const raw=pencilStroke;pencilStroke=null;try{canvas.releasePointerCapture(e.pointerId)}catch{}
 if(e.type==='pointercancel'||raw.length<3){render();return}
 const closed=$('pencilAutoClose').checked&&raw.length>3&&Math.hypot(raw[0].x-raw.at(-1).x,raw[0].y-raw.at(-1).y)<=14/view.scale;
 const shape=globalThis.patternPencil.fit(raw,Number($('pencilSmooth').value)/view.scale,closed);
 if(shape.points.length<2){render();return}
 snapshot();if(piece().points.length){pieces.push(fresh(`Nét tự do ${pieces.length+1}`));active=pieces.length-1}
 Object.assign(piece(),shape,{closed,rawContour:null});hiddenPrevious=false;selected=-1;chosenPieces=new Set([active]);syncPiece();
 status(closed?'Nét tự do đã khép kín. Bấm A để chỉnh điểm hoặc Đưa lên giấy để kiểm tra.':'Đã tạo đường hở. Bấm A để chỉnh, dùng Bút Bézier để nối tiếp hoặc Khép đường đang chọn trước khi đưa lên giấy.');
}
$('closePencilPath').onclick=()=>{const p=piece();if(p.closed||p.points.length<3){status('Chọn đường hở có ít nhất 3 điểm.');return}snapshot();p.closed=true;p.geometrySpec=null;syncPiece();status('Đã nối điểm cuối với điểm đầu. Kiểm tra đường khép trước khi đưa lên giấy.');};

$('sketchToGeometry').onclick=()=>{
 const p=piece();if(p.points.length<2){status('Vẽ hoặc chọn một chi tiết trước khi lấy số đo.');return}
 const b=core.bounds(outline(p)),sx=p.mmPerPixel?.x||(pxPerMm?1/pxPerMm:null),sy=p.mmPerPixel?.y||sx;
 if(!sx||!sy){status('Cần xác định tỷ lệ mm của bản vẽ trước khi lấy kích thước.');return}
 const w=(b.maxX-b.minX)*sx,h=(b.maxY-b.minY)*sy;
 if(w<1||h<1||w>2000||h>2000){status('Kích thước nằm ngoài khoảng 1–2000 mm. Kiểm tra tỷ lệ hoặc chọn chi tiết khác.');return}
 $('geometryWidth').value=w.toFixed(1);$('geometryHeight').value=h.toFixed(1);
 selectRail('railGeometry');$('geometryWidth').dispatchEvent(new Event('input',{bubbles:true}));
 status('Đã lấy kích thước bao của nét phác. Chọn hình, sửa số đo mm và góc bo theo mẫu thật rồi bấm Tạo chi tiết mới. Nét phác được giữ để đối chiếu.');
};
